INSTALL spatial;
LOAD spatial;
INSTALL httpfs;
LOAD httpfs;
SET geometry_always_xy = true;

-- Load input and CAR
CREATE TEMP TABLE input_list AS
SELECT * FROM read_csv('/workspace/lists/goias-sample.csv');

CREATE TEMP TABLE car_data AS
SELECT cod_imovel, geometry as car_geom 
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');

-- Get resolved parcel IDs
CREATE TEMP TABLE resolved_parcels AS
SELECT DISTINCT cod_imovel FROM input_list WHERE cod_imovel IS NOT NULL AND cod_imovel != '';

-- Get envelope (bounding box) of all listed parcels
CREATE TEMP TABLE envelope AS
SELECT ST_Envelope(ST_Union_Agg(ST_GeomFromWKB(car_geom))) as env_geom
FROM car_data
WHERE cod_imovel IN (SELECT cod_imovel FROM resolved_parcels);

-- Load Trazo3 fields
CREATE TEMP TABLE trazo_fields AS
SELECT field_id, geometry as field_geom
FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');

-- Q08: Count fields intersecting envelope
SELECT COUNT(*) as n_fields_in_envelope
FROM trazo_fields
WHERE ST_Intersects(ST_GeomFromWKB(field_geom), (SELECT env_geom FROM envelope));
EOF

